    private static Button B(string text,EventHandler click,int width){var b=new Button{Text=text,Width=width,Height=30,BackColor=Color.FromArgb(42,47,56),ForeColor=Color.White,FlatStyle=FlatStyle.Flat,Margin=new Padding(3)};b.FlatAppearance.BorderSize=0;b.Click+=click;return b;}
    private void OpenPackage(){using var d=new OpenFileDialog{Filter=etmOnly?"Objetos do cenário (*.etm)|*.etm":"Modelos e pacotes (*.bin;*.etm;*.itm)|*.bin;*.etm;*.itm|BIN avulso (*.bin)|*.bin|Pacotes (*.etm;*.itm)|*.etm;*.itm|Todos os arquivos|*.*"};if(d.ShowLocalizedDialog(this)!=DialogResult.OK)return;if(ConfirmPackageSwitch())LoadPackage(d.FileName);}
    public bool LoadPackage(string file){try{if(Path.GetExtension(file).Equals(".bin",StringComparison.OrdinalIgnoreCase)){LoadStandaloneBin(file);UpdatePackageIndicator();return true;}bool nextItm=Path.GetExtension(file).Equals(".itm",StringComparison.OrdinalIgnoreCase);EtmCatalog nextCatalog=nextItm?Ps2ItmReader.Read(file):Ps2EtmReader.Read(file);isItm=nextItm;standaloneBin=false;embeddedDatPath=null;embeddedWeaponParts.Clear();embeddedWeaponTpls=Array.Empty<int>();standaloneBinData=standaloneTplData=null;catalog=nextCatalog;path=file;edits.Clear();editHistory.Clear();previewInitialized=false;dirty=false;objects.Items.Clear();foreach(var o in catalog.Objects.Values.OrderBy(x=>x.Id)){string name=isItm?ItaItemCatalog.GetName(o.Id):$"{EtsObjectNames.Get(o.Id)} (0x{o.Id:X2})";objects.Items.Add(new ObjectItem(o,name));}if(objects.Items.Count>0)objects.SelectedIndex=0;status.Text=$"{Path.GetFileName(file)} • {catalog.Objects.Count} {(isItm?"itens":"objetos")} • {catalog.Resources.Count} recursos";RefreshEtmNavigation();UpdatePackageIndicator();return true;}catch(Exception ex){MessageBox.Show(this,ex.Message,"Não foi possível abrir",MessageBoxButtons.OK,MessageBoxIcon.Error);return false;}}
    private void LoadStandaloneBin(string file){embeddedDatPath=null;embeddedWeaponParts.Clear();embeddedWeaponTpls=Array.Empty<int>();LoadStandaloneData(File.ReadAllBytes(file),null,file,Path.GetFileNameWithoutExtension(file)+" • BIN avulso");}
    private void LoadStandaloneData(byte[] bin,byte[]? tpl,string source,string label){var triangles=Ps2ScenarioReader.ReadStandaloneBin(bin);var br=new EtmResource(0,2,label+".bin",bin);EtmResource? tr=tpl==null?null:new EtmResource(100000,3,label+".tpl",tpl);var rr=tr==null?new[]{br}:new[]{br,tr};standaloneBin=true;isItm=false;standaloneBinData=bin;standaloneTplData=tpl;path=source;edits.Clear();editHistory.Clear();previewInitialized=false;dirty=false;var definition=new EtmObjectDefinition(0,rr);catalog=new EtmCatalog{SourcePath=source,Resources=rr,Objects=new Dictionary<byte,EtmObjectDefinition>{{0,definition}},Models=new Dictionary<byte,IReadOnlyList<ScenarioTriangle>>{{0,triangles}},ModelParts=new Dictionary<byte,IReadOnlyList<EtmModelPart>>{{0,new[]{new EtmModelPart(br,null,tr,triangles)}}}};objects.Items.Clear();objects.Items.Add(new ObjectItem(definition,label));objects.SelectedIndex=0;status.Text=$"{label} • {triangles.Count:N0} triângulos";}
    private void OpenWeaponCatalog(){using var browser=new WeaponDatBrowserForm(workspaceRoot,configuredIso,activeAfsPath,weaponPackagesExtracted);if(browser.ShowLocalizedDialog(this)!=DialogResult.OK||browser.Selection is not WeaponDatSelection selected)return;LoadWeaponDatPackage(selected.DatPath,selected.Parts);}
    private void LoadWeaponDatPackage(string datPath,IReadOnlyList<WeaponDatPartSelection> parts){try{embeddedDatPath=datPath;embeddedWeaponParts.Clear();for(int i=0;i<parts.Count&&i<256;i++)embeddedWeaponParts[(byte)i]=parts[i];var archive=Core.Dat.NativeDatService.Read(datPath);embeddedWeaponTpls=archive.Entries.Where(x=>x.Type.Equals("TPL",StringComparison.OrdinalIgnoreCase)).Select(x=>x.Index).ToArray();standaloneBin=false;standaloneBinData=standaloneTplData=null;isItm=false;path=datPath;edits.Clear();editHistory.Clear();previewInitialized=false;dirty=false;catalog=BuildWeaponCatalog();objects.Items.Clear();foreach(var pair in catalog.Objects.OrderBy(x=>x.Key)){var part=embeddedWeaponParts[pair.Key];objects.Items.Add(new ObjectItem(pair.Value,$"BIN #{part.BinEntry:D3}"+(part.TplEntry>=0?$"  •  TPL #{part.TplEntry:D3}":"  •  sem textura")));}if(objects.Items.Count>0)objects.SelectedIndex=0;status.Text=$"{WeaponNameCatalog.Display(datPath)} • {parts.Count} modelo(s) • {embeddedWeaponTpls.Length} TPL(s)";}catch(Exception ex){embeddedDatPath=null;MessageBox.Show(this,ex.Message,"Não foi possível abrir a arma",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
    private EtmCatalog BuildWeaponCatalog(){if(embeddedDatPath==null)return new();var archive=Core.Dat.NativeDatService.Read(embeddedDatPath);var resources=archive.Entries.Where(x=>x.Type.Equals("BIN",StringComparison.OrdinalIgnoreCase)||x.Type.Equals("TPL",StringComparison.OrdinalIgnoreCase)).ToDictionary(x=>x.Index,x=>new EtmResource(x.Index,x.Type.Equals("BIN",StringComparison.OrdinalIgnoreCase)?2:3,$"{Path.GetFileNameWithoutExtension(embeddedDatPath)}_{x.Index:D3}.{x.Type.ToLowerInvariant()}",edits.TryGetValue(x.Index,out var changed)?changed:x.Data));var objectsById=new Dictionary<byte,EtmObjectDefinition>();var models=new Dictionary<byte,IReadOnlyList<ScenarioTriangle>>();var modelParts=new Dictionary<byte,IReadOnlyList<EtmModelPart>>();foreach(var pair in embeddedWeaponParts){EtmResource bin=resources[pair.Value.BinEntry];EtmResource? active=pair.Value.TplEntry>=0&&resources.TryGetValue(pair.Value.TplEntry,out var t)?t:null;ScenarioTriangle[] triangles=Ps2ScenarioReader.ReadStandaloneBin(bin.Data).ToArray();EtmResource[] visible=new[]{bin}.Concat(embeddedWeaponTpls.Where(resources.ContainsKey).Select(x=>resources[x])).ToArray();objectsById[pair.Key]=new EtmObjectDefinition(pair.Key,visible);models[pair.Key]=triangles;modelParts[pair.Key]=new[]{new EtmModelPart(bin,null,active,triangles)};}return new EtmCatalog{SourcePath=embeddedDatPath,Resources=resources.Values.ToArray(),Objects=objectsById,Models=models,ModelParts=modelParts};}
    private void UseSelectedTpl(){if(embeddedDatPath==null||Selected() is not EtmResource tpl||!tpl.Name.EndsWith(".tpl",StringComparison.OrdinalIgnoreCase)||objects.SelectedItem is not ObjectItem item)return;embeddedWeaponParts[item.Definition.Id]=embeddedWeaponParts[item.Definition.Id] with{TplEntry=tpl.FileOrder};catalog=BuildWeaponCatalog();SelectObject(true);status.Text=$"BIN #{embeddedWeaponParts[item.Definition.Id].BinEntry:D3} testando TPL #{tpl.FileOrder:D3} • associação apenas visual";}
    private void SelectObject(bool preserveView=false){viewport.SetAssetMeshSelection(null);if(catalog==null||objects.SelectedItem is not ObjectItem item)return;int previous=preserveView?(TextureResource()?.FileOrder??-1):-1;EtmCatalog effective=EffectiveCatalog();EtmObjectDefinition o=effective.Objects.TryGetValue(item.Definition.Id,out var current)?current:item.Definition;resources.Items.Clear();foreach(var r in o.Resources){var row=new ListViewItem(r.Name){Tag=r};row.SubItems.Add(r.Name.EndsWith(".bin",StringComparison.OrdinalIgnoreCase)?"Modelo":r.Name.EndsWith(".tpl",StringComparison.OrdinalIgnoreCase)?"Textura":r.Name.EndsWith(".eff",StringComparison.OrdinalIgnoreCase)?"Texturas EFF":$"0x{r.Type:X}");row.SubItems.Add(FormatSize(edits.TryGetValue(r.FileOrder,out var v)?v.Length:r.Data.Length));resources.Items.Add(row);}RefreshPartSelector(effective,o.Id,preserveView);SelectPreferredTextureResource(previous);UpdateStats(effective,o.Id);ShowPreview(effective,o.Id,preserveView);}
    private void UpdateStats(EtmCatalog source,byte id){if(!source.ModelParts.TryGetValue(id,out var parts)){modelStats.Text="SEM GEOMETRIA";return;}var tris=parts.SelectMany(p=>p.Triangles).ToArray();int vertices=0,edges=0,materials=0;foreach(var part in parts){var doc=Ps2BinDocument.Parse(Data(part.Bin));vertices+=doc.Vertices.Count;edges+=doc.Edges.Count;materials+=doc.Materials.Count;}var points=tris.SelectMany(t=>new[]{t.A,t.B,t.C}).ToArray();var min=points.Aggregate(new System.Numerics.Vector3(float.PositiveInfinity),System.Numerics.Vector3.Min);var max=points.Aggregate(new System.Numerics.Vector3(float.NegativeInfinity),System.Numerics.Vector3.Max);var size=max-min;modelStats.Text=$"{tris.Length:N0} faces • {vertices:N0} vértices\n{edges:N0} arestas • {materials} materiais\n{size.X:0.#} × {size.Y:0.#} × {size.Z:0.#}";}
    private void ApplyAssetTranslation(AssetMeshSelection selection,System.Numerics.Vector3 worldDelta){TransformAssetSelection(selection,worldDelta,false);}
    private void ApplyAssetRotation(AssetMeshSelection selection,System.Numerics.Vector3 rotationDegrees){TransformAssetSelection(selection,rotationDegrees,true);}
    private void TransformAssetSelection(AssetMeshSelection selection,System.Numerics.Vector3 value,bool rotate){if(objects.SelectedItem is not ObjectItem item)return;EtmCatalog effective=EffectiveCatalog();if(!effective.ModelParts.TryGetValue(item.Definition.Id,out var parts)||selection.PartIndex<0||selection.PartIndex>=parts.Count)return;EtmModelPart part=parts[activePartOrder>=0?Math.Max(0,parts.ToList().FindIndex(p=>p.Bin.FileOrder==activePartOrder)):selection.PartIndex];if(selection.TriangleIndex<0||selection.TriangleIndex>=part.Triangles.Count)return;ScenarioTriangle tri=part.Triangles[selection.TriangleIndex];int[] Offsets(AssetMeshSelection current){var triangle=part.Triangles[current.TriangleIndex];return current.Mode switch{AssetMeshSelectionMode.Vertex=>new[]{current.ElementIndex==0?triangle.SourceOffsetA:current.ElementIndex==1?triangle.SourceOffsetB:triangle.SourceOffsetC},AssetMeshSelectionMode.Edge=>current.ElementIndex switch{0=>new[]{triangle.SourceOffsetA,triangle.SourceOffsetB},1=>new[]{triangle.SourceOffsetB,triangle.SourceOffsetC},_=>new[]{triangle.SourceOffsetC,triangle.SourceOffsetA}},_=>new[]{triangle.SourceOffsetA,triangle.SourceOffsetB,triangle.SourceOffsetC}};}var selected=viewport.AssetMeshSelections;int[] offsets=selected.Where(x=>x.TriangleIndex>=0&&x.TriangleIndex<part.Triangles.Count).SelectMany(Offsets).Distinct().ToArray();try{var document=Ps2BinDocument.Parse(Data(part.Bin));if(selection.Mode==AssetMeshSelectionMode.Object)offsets=document.Vertices.Select(v=>v.Offset).ToArray();else if(keepConnected.Checked){var selectedPositions=document.Vertices.Where(v=>offsets.Contains(v.Offset)).Select(v=>v.Position).ToArray();const float seamTolerance=.00001f;offsets=document.Vertices.Where(v=>selectedPositions.Any(p=>System.Numerics.Vector3.DistanceSquared(p,v.Position)<=seamTolerance)).Select(v=>v.Offset).ToArray();}if(rotate)document.Rotate(offsets,value);else document.Translate(offsets,value/(isItm?.01f:1f));RecordAssetUndo();edits[part.Bin.FileOrder]=document.Source;Changed($"{selection.Mode} {(rotate?"rotacionado":"movido")}{(keepConnected.Checked&&selection.Mode!=AssetMeshSelectionMode.Object?" • conexões preservadas":"")}");SelectObject(true);viewport.RestoreAssetSelections(selected);}catch(Exception ex){MessageBox.Show(this,ex.Message,"Não foi possível editar a malha",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}
    private void ShowPreview(EtmCatalog effective,byte id,bool preserveView=false){bool fit=!previewInitialized;previewInitialized=true;effective=PreviewCatalog(effective,id);if(!effective.Models.TryGetValue(id,out var mesh)||mesh.Count==0){viewport.SetEtsScene(null,null);viewport.SetItaScene(null,null);viewport.SetScene(new ScenarioScene{BoundsMin=new System.Numerics.Vector3(-1),BoundsMax=new System.Numerics.Vector3(1),Triangles=new()},fit);return;}float scale=isItm?.01f:1f;var points=mesh.SelectMany(t=>new[]{t.A,t.B,t.C}).Select(p=>p*scale).ToArray();var min=points.Aggregate(new System.Numerics.Vector3(float.PositiveInfinity),System.Numerics.Vector3.Min);var max=points.Aggregate(new System.Numerics.Vector3(float.NegativeInfinity),System.Numerics.Vector3.Max);float pad=Math.Max(0.1f,(max-min).Length()*.08f);viewport.SetScene(new ScenarioScene{BoundsMin=min-new System.Numerics.Vector3(pad),BoundsMax=max+new System.Numerics.Vector3(pad),Triangles=new()},fit);if(isItm){var scene=new ItaScene();scene.Entries.Add(new ItaEntry{ItemId=id,FileOrder=0,AppearanceType=0});viewport.SetEtsScene(null,null);viewport.SetItaScene(scene,effective);viewport.SelectItaEntry(scene.Entries[0]);}else{var scene=new EtsScene();scene.Entries.Add(new EtsEntry{ObjectId=id,InstanceIndex=0,ScaleX=1,ScaleY=1,ScaleZ=1});viewport.SetItaScene(null,null);viewport.SetEtsScene(scene,effective);viewport.SelectEtsEntry(scene.Entries[0]);}viewport.Invalidate();}
    private EtmCatalog EffectiveCatalog(){if(catalog==null||path==null)return new();if(embeddedDatPath!=null)return BuildWeaponCatalog();if(standaloneBin){byte[] bin=edits.TryGetValue(0,out var edited)?edited:standaloneBinData!;var triangles=Ps2ScenarioReader.ReadStandaloneBin(bin);var br=new EtmResource(0,2,Path.GetFileName(path),bin);byte[]? tplBytes=edits.TryGetValue(100000,out var editedTpl)?editedTpl:standaloneTplData;EtmResource? tpl=tplBytes==null?null:new EtmResource(100000,3,Path.GetFileNameWithoutExtension(path)+".tpl",tplBytes);var all=tpl==null?new[]{br}:new[]{br,tpl};var definition=new EtmObjectDefinition(0,all);return new EtmCatalog{SourcePath=path,Resources=all,Objects=new Dictionary<byte,EtmObjectDefinition>{{0,definition}},Models=new Dictionary<byte,IReadOnlyList<ScenarioTriangle>>{{0,triangles}},ModelParts=new Dictionary<byte,IReadOnlyList<EtmModelPart>>{{0,new[]{new EtmModelPart(br,null,tpl,triangles)}}}};}var temp=Path.Combine(Path.GetTempPath(),"asset_preview_"+Guid.NewGuid().ToString("N")+Path.GetExtension(path));Ps2AssetPackageEditor.Save(path,temp,edits);try{return Path.GetExtension(path).Equals(".itm",StringComparison.OrdinalIgnoreCase)?Ps2ItmReader.Read(temp):Ps2EtmReader.Read(temp);}finally{try{File.Delete(temp);}catch{}}}
    private void LoadStandaloneTpl(){if(!standaloneBin){MessageBox.Show(this,"O carregamento separado de TPL é usado quando um BIN avulso está aberto.","Carregar textura",MessageBoxButtons.OK,MessageBoxIcon.Information);return;}using var d=new OpenFileDialog{Filter="Pacote de texturas TPL (*.tpl)|*.tpl|Todos os arquivos|*.*"};if(d.ShowLocalizedDialog(this)!=DialogResult.OK)return;try{byte[] candidate=File.ReadAllBytes(d.FileName);using(var ms=new MemoryStream(candidate))using(var br=new BinaryReader(ms))new TplReader().ReadTexture(br,0);standaloneTplData=candidate;catalog=EffectiveCatalog();objects.Items.Clear();objects.Items.Add(new ObjectItem(catalog.Objects[0],Path.GetFileNameWithoutExtension(path)+" • BIN + TPL"));objects.SelectedIndex=0;status.Text=$"{Path.GetFileName(path)} • textura {Path.GetFileName(d.FileName)} carregada";}catch(Exception ex){MessageBox.Show(this,ex.Message,"TPL inválido",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}
    private EtmResource? Selected()=>resources.SelectedItems.Count==0?null:resources.SelectedItems[0].Tag as EtmResource;
