    private void ReplaceSelected(){var r=Selected();if(r==null)return;using var d=new OpenFileDialog{Filter=r.Name.EndsWith(".bin",StringComparison.OrdinalIgnoreCase)?"Modelo BIN do PS2 (*.bin)|*.bin|Todos os arquivos|*.*":"Arquivo compatível|*.*"};if(d.ShowLocalizedDialog(this)!=DialogResult.OK)return;byte[] candidate=File.ReadAllBytes(d.FileName);if(r.Name.EndsWith(".bin",StringComparison.OrdinalIgnoreCase)){try{Ps2ScenarioReader.ReadStandaloneBin(candidate);}catch(Exception ex){MessageBox.Show(this,"Esse BIN não contém uma malha PS2 compatível.\n\n"+ex.Message,"Modelo inválido",MessageBoxButtons.OK,MessageBoxIcon.Warning);return;}}RecordAssetUndo();edits[r.FileOrder]=candidate;Changed($"{r.Name} substituído");SelectObject();}
    private async Task ImportExternalModelAsync()
    {
        if(catalog==null||objects.SelectedItem is not ObjectItem selectedObject){MessageBox.Show(this,"Abra um modelo e selecione o objeto que receberá a nova malha.","Importar modelo",MessageBoxButtons.OK,MessageBoxIcon.Information);return;}EtmCatalog effective=EffectiveCatalog();if(!effective.ModelParts.TryGetValue(selectedObject.Definition.Id,out var parts)||parts.Count==0){MessageBox.Show(this,"O objeto selecionado não possui um BIN receptor.","Importar modelo",MessageBoxButtons.OK,MessageBoxIcon.Information);return;}EtmModelPart receiver=parts.FirstOrDefault(p=>p.Bin.FileOrder==activePartOrder)??parts[0];using var file=new OpenFileDialog{Title="Escolha o modelo externo",Filter="Modelos compatíveis (*.obj;*.smd)|*.obj;*.smd|Wavefront OBJ (*.obj)|*.obj|StudioModelData com ossos (*.smd)|*.smd"};if(file.ShowLocalizedDialog(this)!=DialogResult.OK)return;
        try
        {
            ExternalModelStats stats=Ps2ModelConversionService.Analyze(file.FileName);byte[] template=Data(receiver.Bin);bool hasBones=false;try{hasBones=Core.Animation.Ps2BinSkeletonReader.Read(template,"receiver").Bones.Count>0;}catch{}using var wizard=new ExternalModelImportDialog(file.FileName,stats,hasBones,receiver.Triangles,preserveFileTransform:Path.GetExtension(path).Equals(".etm",StringComparison.OrdinalIgnoreCase));if(wizard.ShowLocalizedDialog(this)!=DialogResult.OK)return;UseWaitCursor=true;status.Text=$"Convertendo {Path.GetFileName(file.FileName)} para o formato BIN do PS2...";string generated=await Ps2ModelConversionService.ConvertAsync(file.FileName,template,wizard.AutoWeight,default,wizard.Options);try{byte[] converted=File.ReadAllBytes(generated);var parsed=Ps2BinDocument.Parse(converted);if(parsed.Faces.Count==0)throw new InvalidDataException("O BIN convertido não contém faces renderizáveis.");var pending=new Dictionary<int,byte[]> { [receiver.Bin.FileOrder]=converted };if(wizard.ImportCompanionTexture){EtmResource? source=receiver.TextureFallback??receiver.Effect;if(source==null)throw new InvalidDataException("Este BIN não possui TPL/EFF para receber a textura.");pending[source.FileOrder]=PrepareCompanionImages(source,receiver,file.FileName);}RecordAssetUndo();foreach(var change in pending)edits[change.Key]=change.Value;Changed($"{Path.GetFileName(file.FileName)} importado • {stats.Vertices:N0} vértices • {stats.Faces:N0} faces");SelectObject(true);}finally{try{File.Delete(generated);}catch{}}
        }
        catch(Exception ex){MessageBox.Show(this,ex.Message,"Não foi possível importar o modelo",MessageBoxButtons.OK,MessageBoxIcon.Error);}
        finally{UseWaitCursor=false;}
    }

    private void RestoreSelected(){var r=Selected();if(r==null)return;if(!edits.ContainsKey(r.FileOrder))return;RecordAssetUndo();edits.Remove(r.FileOrder);dirty=edits.Count>0;UpdatePackageIndicator();status.Text=dirty?$"{r.Name} restaurado • alterações pendentes":$"{r.Name} restaurado • pacote sem alterações";SelectObject();}
    private void ExportPng(){ExportSelectedPng();}
    private void ReplacePng()=>ReplaceTextureImage();
    private void TransformSelectedTexture(RotateFlipType transform,string description,bool preserveDimensions)
    {
        var resource=TextureResource();if(resource==null)return;
        int index=CurrentTextureIndex;
        string temp=Path.Combine(Path.GetTempPath(),"asset_texture_"+Guid.NewGuid().ToString("N")+".tpl");
        try
        {
            byte[] changed;
            if(IsEff(resource))changed=EffEmbeddedTextureExporter.Transform(Data(resource),index,transform);
            else
            {
                File.WriteAllBytes(temp,Data(resource));using Bitmap bitmap=DecodeSelectedTexture(resource,index);bitmap.RotateFlip(transform);
                new TextureWorkspaceService().ReplaceFromBitmap(temp,index,bitmap,preserveDimensions);changed=File.ReadAllBytes(temp);
            }
            RecordAssetUndo();edits[resource.FileOrder]=changed;Changed($"Textura #{index} {description}");SelectObject(true);
            SelectPreferredTextureResource(resource.FileOrder);textureIndex.SelectedIndex=Math.Min(index,textureIndex.Items.Count-1);
        }
        catch(Exception ex){MessageBox.Show(this,ex.Message,"Transformar textura",MessageBoxButtons.OK,MessageBoxIcon.Error);}
        finally{if(File.Exists(temp))File.Delete(temp);}
    }
    private void Save(bool choose){if(path==null)return;string destination=path;if(choose){using var d=new SaveFileDialog{FileName=Path.GetFileName(path),Filter=embeddedDatPath!=null?"Pacote de arma DAT (*.dat)|*.dat":standaloneBin?"Modelo BIN (*.bin)|*.bin|Todos os arquivos|*.*":"Pacote de objetos|*.etm;*.itm|Todos os arquivos|*.*"};if(d.ShowLocalizedDialog(this)!=DialogResult.OK)return;destination=d.FileName;}var view=CaptureEditorView();try{if(embeddedDatPath!=null){string source=embeddedDatPath;if(choose&&!Path.GetFullPath(source).Equals(Path.GetFullPath(destination),StringComparison.OrdinalIgnoreCase))File.Copy(source,destination,true);if(!File.Exists(destination+".bak"))File.Copy(destination,destination+".bak");foreach(var edit in edits)Ps2CharacterDatEditor.RestoreDatEntry(destination,edit.Key,edit.Value);SyncWeaponContentEntries(destination,edits);WeaponDatPartSelection[] mappings=embeddedWeaponParts.OrderBy(x=>x.Key).Select(x=>x.Value).ToArray();LoadWeaponDatPackage(destination,mappings);}else{if(!choose&&!File.Exists(path+".bak"))File.Copy(path,path+".bak");if(standaloneBin)File.WriteAllBytes(destination,edits.TryGetValue(0,out var bin)?bin:standaloneBinData!);else Ps2AssetPackageEditor.Save(path,destination,edits);LoadPackage(destination);}RestoreEditorView(view);status.Text="Salvo com sucesso • backup preservado";}catch(Exception ex){MessageBox.Show(this,ex.Message,"Falha ao salvar");}}
    private static void SyncWeaponContentEntries(string datPath,IReadOnlyDictionary<int,byte[]> changed){if(changed.Count==0)return;string? directory=Path.GetDirectoryName(datPath);if(directory==null||!Directory.Exists(directory)||!Directory.EnumerateFiles(directory,"*.idx",SearchOption.TopDirectoryOnly).Any())return;string name=Path.GetFileNameWithoutExtension(datPath);foreach(var edit in changed){string marker=$"_{edit.Key:D2}.";string marker3=$"_{edit.Key:D3}.";string? entry=Directory.EnumerateFiles(directory,name+"_*.*",SearchOption.AllDirectories).FirstOrDefault(x=>Path.GetFileName(x).Contains(marker,StringComparison.OrdinalIgnoreCase)||Path.GetFileName(x).Contains(marker3,StringComparison.OrdinalIgnoreCase));if(entry!=null)File.WriteAllBytes(entry,edit.Value);}}
    private void Changed(string message){dirty=true;status.Text=message+" • alterações pendentes";UpdatePackageIndicator();}
    private void OnClosing(object? s,FormClosingEventArgs e){if(!ConfirmPackageSwitch())e.Cancel=true;}
    private static string FormatSize(long b)=>b<1024?$"{b} B":b<1048576?$"{b/1024d:0.0} KB":$"{b/1048576d:0.0} MB";
}
